function longestCommonSubsequence(first: string, second: string): number {
  const rows = first.length;
  const cols = second.length;
  // table[i][j] is the answer for the first i letters of first and the first j of second.
  const table: number[][] = Array.from({ length: rows + 1 }, () => new Array<number>(cols + 1).fill(0));
  for (let i = 1; i <= rows; i++) {
    const row = table[i] ?? [];
    const above = table[i - 1] ?? [];
    for (let j = 1; j <= cols; j++) {
      if (first[i - 1] === second[j - 1]) {
        row[j] = (above[j - 1] ?? 0) + 1;
      } else {
        row[j] = Math.max(above[j] ?? 0, row[j - 1] ?? 0);
      }
    }
  }
  return table[rows]?.[cols] ?? 0;
}

const [first = "", second = ""] = input.trim().split(/\s+/);
console.log(longestCommonSubsequence(first, second));
